  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Premazepam, a structurally related fused-ring benzodiazepine-like molecule, readily crossed the blood-brain barrier in monkey whole-body autoradiography, supporting CNS access for the query's similar lipophilic fused heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "MK-801, a lipophilic tricyclic amine with a high assay-transfer score, achieved a brain-to-plasma ratio greater than 10:1 in rats, demonstrating that this structural class can penetrate the CNS extensively despite basic amine character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Stobadine, a close tricyclic amine analogue, showed a brain uptake index of 78% in rats, directly indicating ready passage across the blood-brain barrier for a molecule with similar physicochemical features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Mianserin, a tetracyclic antidepressant containing an N-methylpiperazine moiety, showed a logBB of 0.99 in rats, providing direct evidence that the query's piperazine-bearing lipophilic scaffold is brain-penetrating.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is olanzapine, a known CNS-active thienobenzodiazepine with an N-methylpiperazine side chain. Multiple high-transfer in vivo analogues—including premazepam, MK-801, stobadine, and mianserin—consistently demonstrate good to excellent brain penetration. The physicochemical prior also supports high passive BBB permeability. Therefore, the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct olanzapine-specific brain/plasma or CSF measurement is present in the supplied evidence set.",
    "Reliance on close analogues rather than a direct human PET or CSF study for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

